/** ۱) ثبت تاکسونومی‌های دانشمند (اگر پوسته ثبت نکرده باشد). */
function qpsi_register_taxonomies() {
	if ( ! taxonomy_exists( 'scientist_field' ) ) {
		register_taxonomy( 'scientist_field', 'quantum_scientist', array(
			'labels'            => array( 'name' => 'زمینهٔ علمی', 'singular_name' => 'زمینه', 'menu_name' => 'زمینهٔ علمی' ),
			'hierarchical'      => false,
			'public'            => true,
			'show_ui'           => true,
			'show_admin_column' => true,
			'show_in_rest'      => true,
			'rewrite'           => array( 'slug' => 'scientist-field', 'with_front' => false ),
		) );
	}
	if ( ! taxonomy_exists( 'quantum_scientist_group' ) ) {
		register_taxonomy( 'quantum_scientist_group', 'quantum_scientist', array(
			'labels'            => array( 'name' => 'گروه دانشمندان', 'singular_name' => 'گروه', 'menu_name' => 'گروه دانشمندان' ),
			'hierarchical'      => true,
			'public'            => true,
			'show_ui'           => true,
			'show_admin_column' => true,
			'show_in_rest'      => true,
			'rewrite'           => array( 'slug' => 'scientist-group', 'with_front' => false ),
		) );
	}
}
add_action( 'init', 'qpsi_register_taxonomies', 9 );

