/** ۳) یافتن/ساخت عبارت در یک تاکسونومی با نام فارسی. */
function qpsi_term_id_by_name( $name, $taxonomy ) {
	$name = trim( (string) $name );
	if ( '' === $name || ! taxonomy_exists( $taxonomy ) ) { return 0; }
	$term = get_term_by( 'name', $name, $taxonomy );
	if ( $term && ! is_wp_error( $term ) ) { return (int) $term->term_id; }
	$r = wp_insert_term( $name, $taxonomy );
	if ( is_wp_error( $r ) ) {
		$data = $r->get_error_data();
		if ( isset( $data['term_exists'] ) ) { return (int) $data['term_exists']; }
		return 0;
	}
	return (int) $r['term_id'];
}

/** ۴) صفحهٔ ابزار. */
add_action( 'admin_menu', 'qpsi_admin_menu' );
function qpsi_admin_menu() {
	add_management_page( 'ورود دانشمندان کیوپدیا', 'ورود دانشمندان کیوپدیا', 'edit_posts', 'qpsi', 'qpsi_screen' );
}

function qpsi_screen() {
	if ( ! current_user_can( 'edit_posts' ) ) { wp_die( 'دسترسی ندارید.' ); }
	$items = qpsi_payload();

	echo '<div class="wrap" dir="rtl"><h1>ورود دانشمندان کیوپدیا</h1>';
	echo '<p>' . count( $items ) . ' مدخلِ دانشمند، آمادهٔ ورود به‌صورت <strong>پیش‌نویس</strong> در «دانشمندان کوانتوم» (quantum_scientist).</p>';

	if ( isset( $_POST['qpsi_go'] ) && check_admin_referer( 'qpsi_run' ) ) {
		$new = 0; $upd = 0; $err = 0; $skip = 0;
		echo '<div class="notice notice-info"><ul>';
		foreach ( $items as $it ) {
			$slug    = isset( $it['slug'] ) ? sanitize_title( $it['slug'] ) : '';
			$title   = isset( $it['title'] ) ? $it['title'] : '';
			$content = isset( $it['content'] ) ? $it['content'] : '';
			$excerpt = isset( $it['excerpt'] ) ? $it['excerpt'] : '';

			$existing = get_posts( array(
				'post_type'      => 'quantum_scientist',
				'name'           => $slug,
				'post_status'    => array( 'publish', 'draft', 'pending', 'private', 'future' ),
				'posts_per_page' => 1,
				'fields'         => 'ids',
			) );

			$args = array(
				'post_type'    => 'quantum_scientist',
				'post_title'   => $title,
				'post_name'    => $slug,
				'post_content' => $content,
				'post_excerpt' => $excerpt,
				'post_status'  => 'draft',
			);

			if ( ! empty( $existing ) ) {
				$prev_status = get_post_status( (int) $existing[0] );
				if ( 'publish' === $prev_status ) {
					$skip++;
					echo '<li>⚠️ رد شد (قبلاً منتشر شده) — <a href="' . esc_url( get_edit_post_link( (int) $existing[0] ) ) . '">' . esc_html( $title ) . '</a></li>';
					continue;
				}
				$args['ID'] = (int) $existing[0];
				$id         = wp_update_post( $args );
				$verb       = 'به‌روزرسانی';
				$upd++;
			} else {
				$id   = wp_insert_post( $args );
				$verb = 'ایجاد';
				$new++;
			}

			if ( $id && ! is_wp_error( $id ) ) {
				if ( ! empty( $it['en_name'] ) ) { update_post_meta( $id, '_scientist_en_name', $it['en_name'] ); }
				if ( ! empty( $it['seo_title'] ) ) { update_post_meta( $id, '_qpedia_seo_title', $it['seo_title'] ); }
				if ( ! empty( $it['meta_description'] ) ) { update_post_meta( $id, '_qpedia_meta_description', $it['meta_description'] ); }
				if ( ! empty( $it['focus_keyphrase'] ) ) { update_post_meta( $id, '_qpedia_focus_keyphrase', $it['focus_keyphrase'] ); }

				$field_id = qpsi_term_id_by_name( isset( $it['field'] ) ? $it['field'] : '', 'scientist_field' );
				if ( $field_id ) { wp_set_object_terms( $id, array( $field_id ), 'scientist_field' ); }

				$group_id = qpsi_term_id_by_name( isset( $it['group'] ) ? $it['group'] : '', 'quantum_scientist_group' );
				if ( $group_id ) { wp_set_object_terms( $id, array( $group_id ), 'quantum_scientist_group' ); }

				echo '<li>✅ ' . esc_html( $verb ) . ' — <a href="' . esc_url( get_edit_post_link( $id ) ) . '">' . esc_html( $title ) . '</a></li>';
			} else {
				$err++;
				echo '<li>❌ ناموفق — ' . esc_html( $title ) . '</li>';
			}
		}
		echo '</ul><p><strong>' . intval( $new ) . ' ایجاد · ' . intval( $upd ) . ' به‌روزرسانی · ' . intval( $skip ) . ' ردشده (منتشر) · ' . intval( $err ) . ' خطا</strong></p></div>';
		echo '<p><a class="button button-primary" href="' . esc_url( admin_url( 'edit.php?post_type=quantum_scientist&post_status=draft' ) ) . '">دیدن پیش‌نویس‌ها</a></p>';
		echo '<div class="notice notice-warning"><p>ورود تمام شد. پس از بررسی و انتشار، <strong>این افزونه را حذف کنید</strong>.</p></div>';
	} else {
		echo '<table class="widefat striped" style="max-width:1080px"><thead><tr><th>عنوان</th><th>اسلاگ</th><th>زمینه</th><th>گروه</th><th>حجم</th><th>وضعیت</th></tr></thead><tbody>';
		foreach ( $items as $it ) {
			$size   = isset( $it['content'] ) ? mb_strlen( $it['content'] ) : 0;
			$status = '—';
			$slug   = isset( $it['slug'] ) ? sanitize_title( $it['slug'] ) : '';
			if ( '' !== $slug ) {
				$ex = get_posts( array(
					'post_type'      => 'quantum_scientist',
					'name'           => $slug,
					'post_status'    => array( 'publish', 'draft', 'pending', 'private', 'future' ),
					'posts_per_page' => 1,
					'fields'         => 'ids',
				) );
				if ( ! empty( $ex ) ) {
					$status = ( 'publish' === get_post_status( (int) $ex[0] ) ) ? '<span style="color:#b32d2e">⚠ منتشر است</span>' : '<span style="color:#997404">پیش‌نویس موجود</span>';
				}
			}
			echo '<tr><td>' . esc_html( isset( $it['title'] ) ? $it['title'] : '' ) . '</td><td><code>' . esc_html( $slug ) . '</code></td><td>' . esc_html( isset( $it['field'] ) ? $it['field'] : '' ) . '</td><td>' . esc_html( isset( $it['group'] ) ? $it['group'] : '' ) . '</td><td>' . number_format_i18n( $size ) . ' نویسه</td><td>' . $status . '</td></tr>';
		}
		echo '</tbody></table><form method="post" style="margin-top:18px">';
		wp_nonce_field( 'qpsi_run' );
		echo '<button name="qpsi_go" class="button button-primary button-hero">ورود ۳۲ دانشمند به‌صورت پیش‌نویس</button></form>';
		echo '<div class="notice notice-info"><p>نکته: مدخلی که <strong>منتشر شده</strong> باشد هرگز بازنویسی نمی‌شود و رد می‌شود؛ پیش‌نویسِ موجود به‌روزرسانی می‌شود. تاکسونومی‌های «زمینهٔ علمی» و «گروه دانشمندان» در صورت نبود ثبت می‌شوند و عبارت‌ها ساخته می‌شوند.</p></div>';
	}

	echo '</div>';
}
